const filas = $input.all().map((i) => i.json);
const parametro = $('Parsear y validar intencion').first().json.parametro;

const valores = filas.map((f) => f.valor);
const promedio = valores.reduce((a, b) => a + b, 0) / valores.length;
const maximo = Math.max(...valores);
const minimo = Math.min(...valores);

const sistema = 'Explicas datos de calidad del aire de Lima, Peru, en espanol claro, para un ciudadano sin '
  + 'formacion tecnica. Maximo 4 oraciones. No inventes cifras: usa unicamente las que se te dan.';

const usuario = `Parametro: ${parametro}\n`
  + `Cantidad de mediciones: ${filas.length}\n`
  + `Promedio: ${promedio.toFixed(1)}\n`
  + `Maximo: ${maximo}\n`
  + `Minimo: ${minimo}\n`
  + `Redacta un resumen breve para el usuario.`;

return [{
  json: {
    resumen_datos: { promedio, maximo, minimo, cantidad: filas.length },
    groq_payload: {
      model: 'llama-3.3-70b-versatile',
      messages: [{ role: 'system', content: sistema }, { role: 'user', content: usuario }],
      temperature: 0.4, max_tokens: 250,
    },
    gemini_payload: {
      contents: [{ parts: [{ text: `${sistema}\n\n${usuario}` }] }],
      generationConfig: { temperature: 0.4, maxOutputTokens: 250 },
    },
  },
}];

const r = $input.item.json;
let texto = 'No fue posible redactar el resumen automaticamente.';
let modelo = 'ninguno';

if (r.choices && r.choices[0]) { texto = r.choices[0].message.content.trim(); modelo = 'groq-llama-3.3-70b'; }
else if (r.candidates && r.candidates[0]) { texto = r.candidates[0].content.parts[0].text.trim(); modelo = 'gemini-3.5-flash-lite'; }

const filas = $('Consultar historico (parametrizado)').all().map((i) => i.json);
const intencion = $('Parsear y validar intencion').first().json;

return {
  json: {
    ok: true, codigo_http: 200, texto, modelo_usado: modelo,
    parametro: intencion.parametro,
    rango: { desde: intencion.desde, hasta: intencion.hasta },
    serie: filas.map((f) => ({ x: f.medido_en, y: f.valor, estacion: f.estacion })),
  },
};

